func RunsInContainer(r *Report, tools config.ScanTools, ids []ToolID) bool {
	for _, id := range ids {
		if r != nil {
			if st, ok := r.Tools[id]; ok && st.Available && st.Source == ToolSourceContainer {
				return true
			}
			continue
		}
		if tc := tools.Tool(string(id)); tc != nil && tc.Source == config.ToolSourceImage {
			return true
		}
	}
	return false
}

func ContainerProxyWarning(fwd netproxy.Forward, containerised bool) string {
	if !containerised {
		return ""
	}
	v, display, ok := fwd.Loopback()
	if !ok {
		return ""
	}
	return fmt.Sprintf("%s is %s, on this machine's loopback: scanner containers cannot reach it", v, display)
}
